// Hand-crafted code samples for the flagship endpoints.
//
// Per docs/SCALAR_DOCS_ENHANCEMENT_PLAN.md §10 +
// docs/development/sdks/SDK_PUBLIC_DOCUMENTATION.md. Each entry is keyed
// by (method, path); applyCodeSamples() walks the generated OpenAPI doc
// and attaches `x-codeSamples` to the matching operation. operationIds
// are auto-generated by @hono/zod-openapi, so keying by (method, path)
// is the durable contract.
//
// Languages:
//   * shell  — curl, the "no-deps" tab
//   * js     — Node SDK (@textral/sdk)
//   * python — Python SDK (textral)
//
// Curl samples use placeholder strings the user replaces:
//   {{TENANT_API_KEY}}  → their own X-Textral-Api-Key
//   {{WORKER_URL}}      → e.g. https://textral-api-dev.<sub>.workers.dev
//
// SDK samples use **profile mode** — the canonical credential path,
// `~/.textral/profiles.toml`. Explicit `baseUrl` / `apiKey` is shown
// in the SDK pages; samples pick one path and stick with it so each
// snippet is paste-and-run with no editing.

export interface CodeSample {
  lang: 'shell' | 'js' | 'python';
  label: string;
  source: string;
}

export interface SampleKey {
  method: 'get' | 'post' | 'put' | 'delete' | 'patch';
  path: string;
}

interface SampleEntry {
  key: SampleKey;
  samples: CodeSample[];
}

const KEY = '{{TENANT_API_KEY}}';
const URL_ = '{{WORKER_URL}}';

// ── SDK sample builders ─────────────────────────────────────────────
//
// Each entry's js/python sample is one client construction +
// one call. The helpers fold the imports + boilerplate into
// per-entry one-liners so the file stays reviewable as new
// endpoints land.

function nodeSdk(callBody: string, label = 'Node (@textral/sdk)'): CodeSample {
  return {
    lang: 'js',
    label,
    source: `import { TextralClient } from '@textral/sdk';

const client = new TextralClient({ profile: 'hosted-prod' });

${callBody}`,
  };
}

function pythonSdk(callBody: string, label = 'Python (textral)'): CodeSample {
  return {
    lang: 'python',
    label,
    source: `from textral import Client

with Client(profile="hosted-prod") as client:
${callBody}`,
  };
}

