// ─── 8. Poll an ingestion job ─────────────────────────────────────
const POLL_JOB: SampleEntry = {
  key: { method: 'get', path: '/v1/ingestion-jobs/{id}' },
  samples: [
    {
      lang: 'shell',
      label: 'curl',
      source: `# Polling loop (simplified).
while true; do
  STATUS=$(curl -s "${URL_}/v1/ingestion-jobs/$JOB_ID" \\
    -H "X-Textral-Api-Key: ${KEY}" | jq -r .status)
  echo "status: $STATUS"
  case "$STATUS" in
    completed|failed) break ;;
    *) sleep 5 ;;
  esac
done`,
    },
    nodeSdk(`async function pollJob(jobId: string, timeoutMs = 240_000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const j = await client.ingestionJobs.get(jobId);
    if (j.status === 'completed' || j.status === 'failed') return j;
    await new Promise((r) => setTimeout(r, 5_000));
  }
  throw new Error('job poll timed out');
}`),
    pythonSdk(`    import time

    def poll_job(job_id: str, timeout_s: int = 240):
        start = time.time()
        while time.time() - start < timeout_s:
            j = client.ingestion_jobs.get(job_id)
            if j["status"] in ("completed", "failed"):
                return j
            time.sleep(5)
        raise TimeoutError("job poll timed out")`),
  ],
};

