// ─── 10. Streaming query (SSE) ────────────────────────────────────
// Same path as #9 but with ?stream=sse — Scalar shows it as a
// separate operation only if we register it as one. For now we
// document it inside the sync query's description and as a
// snippet here keyed on the same path; the renderer dedupes by
// (path, method) so we attach this as an *additional* sample on
// the sync query.
const STREAMING_QUERY_SAMPLE: CodeSample[] = [
  {
    lang: 'shell',
    label: 'curl (?stream=sse)',
    source: `curl -N -X POST "${URL_}/v1/query?stream=sse" \\
  -H "X-Textral-Api-Key: ${KEY}" \\
  -H 'accept: text/event-stream' \\
  -H 'content-type: application/json' \\
  -d '{
    "namespace": "my-docs",
    "query": "What does the doc say about X?",
    "embedding": { "provider": "openai", "model": "text-embedding-3-large", "dimensions": 1536, "provider_key_ref": "default" },
    "inference": { "provider": "openai", "model": "gpt-4o-mini", "provider_key_ref": "default" },
    "chunking": { "profile": "generic" },
    "retrieval": { "strategy": "hybrid_rrf", "top_k_dense": 5, "top_k_sparse": 5 }
  }'

# Two event types: token (per delta) and done (single final event).`,
  },
  {
    lang: 'js',
    label: 'Node SDK — streaming',
    source: `import { TextralClient } from '@textral/sdk';

const client = new TextralClient({ profile: 'hosted-prod' });

for await (const frame of client.query.stream({
  namespace: 'my-docs',
  query: 'What does the doc say about X?',
  embedding: { provider: 'openai', model: 'text-embedding-3-large', dimensions: 1536, provider_key_ref: 'default' },
  inference:  { provider: 'openai', model: 'gpt-4o-mini', provider_key_ref: 'default' },
  chunking:   { profile: 'generic' },
  retrieval:  { strategy: 'hybrid_rrf', top_k_dense: 5, top_k_sparse: 5 },
})) {
  if (frame.type === 'token') process.stdout.write(frame.value);
  else if (frame.type === 'done') console.log('\\n', frame.degradation_level);
}`,
  },
  {
    lang: 'python',
    label: 'Python SDK — streaming (async)',
    source: `import asyncio
from textral import AsyncClient

async def main():
    async with AsyncClient(profile="hosted-prod") as client:
        async for frame in client.query.stream(
            namespace="my-docs",
            query="What does the doc say about X?",
            embedding={"provider": "openai", "model": "text-embedding-3-large", "dimensions": 1536, "provider_key_ref": "default"},
            inference={"provider": "openai", "model": "gpt-4o-mini", "provider_key_ref": "default"},
            chunking={"profile": "generic"},
            retrieval={"strategy": "hybrid_rrf", "top_k_dense": 5, "top_k_sparse": 5},
        ):
            if frame.get("event") == "answer_token":
                print(frame.get("value", ""), end="", flush=True)
            elif frame.get("event") == "final":
                print()
                print(f"degradation: {frame.get('degradation_level')}")

asyncio.run(main())`,
  },
];

