// ─── 11. Bulk ingest (orchestrator) ───────────────────────────────
// New entry — the SDKs each ship a `bulkIngestOrchestrate` /
// `bulk_ingest_orchestrate` helper that drives the manifest →
// parallel uploads → optional finalize → poll dance in one call.
// Curl needs the manual three-step dance; SDK samples use the helper.
const BULK_INGEST: SampleEntry = {
  key: { method: 'post', path: '/v1/ingest/bulk' },
  samples: [
    {
      lang: 'shell',
      label: 'curl (manual three-step)',
      source: `# 1) Submit manifest. Server returns one upload URL per file.
SUBMIT_JSON=$(curl -s -X POST "${URL_}/v1/ingest/bulk" \\
  -H "X-Textral-Api-Key: ${KEY}" \\
  -H 'content-type: application/json' \\
  -d '{
    "namespace": "my-docs",
    "config": {
      "embedding": { "provider": "openai", "model": "text-embedding-3-large", "dimensions": 1536, "provider_key_ref": "default" },
      "chunking":  { "profile": "generic" },
      "mode": "full"
    },
    "files": [
      { "ordinal": 0, "filename": "a.md", "size_bytes": 1234, "content_type": "text/markdown" },
      { "ordinal": 1, "filename": "b.md", "size_bytes": 5678, "content_type": "text/markdown" }
    ],
    "on_existing": "skip_if_unchanged",
    "auto_finalize": true
  }')

BULK_JOB_ID=$(echo "$SUBMIT_JSON" | jq -r .bulk_job_id)

# 2) PUT each file's bytes to its server-minted upload_url (parallel).
echo "$SUBMIT_JSON" | jq -c .uploads[] | while read SLOT; do
  ORDINAL=$(echo "$SLOT" | jq -r .ordinal)
  URL=$(echo "$SLOT" | jq -r .upload_url)
  case "$ORDINAL" in
    0) FILE=./a.md ;;
    1) FILE=./b.md ;;
  esac
  curl -X PUT "$URL" -H 'content-type: text/markdown' --data-binary @"$FILE" &
done
wait

# 3) (auto_finalize: true above) Poll until terminal.
while true; do
  STATE=$(curl -s "${URL_}/v1/ingest/bulk/$BULK_JOB_ID" \\
    -H "X-Textral-Api-Key: ${KEY}" | jq -r .state)
  echo "state: $STATE"
  case "$STATE" in
    complete|partial|failed|cancelled|expired) break ;;
    *) sleep 2 ;;
  esac
done`,
    },
    {
      lang: 'js',
      label: 'Node SDK — bulkIngestOrchestrate',
      source: `import { TextralClient, bulkIngestOrchestrate } from '@textral/sdk';
import { readFileSync, statSync } from 'node:fs';

const client = new TextralClient({ profile: 'hosted-prod' });

const result = await bulkIngestOrchestrate(client, {
  namespace: 'my-docs',
  config: {
    embedding: { provider: 'openai', model: 'text-embedding-3-large', dimensions: 1536, provider_key_ref: 'default' },
    chunking:  { profile: 'generic' },
    mode: 'full',
  },
  files: ['a.md', 'b.md'].map((name) => ({
    filename: name,
    bytes: readFileSync(name),
    size_bytes: statSync(name).size,
    content_type: 'text/markdown',
  })),
  on_existing: 'skip_if_unchanged',
  auto_finalize: true,
  concurrency: 4,
  onProgress: (snap) => console.log(snap.state, snap.progress_pct + '%'),
});
console.log(result.bulk_job_id, result.final_status.state);`,
    },
    {
      lang: 'python',
      label: 'Python SDK — bulk_ingest_orchestrate',
      source: `from pathlib import Path
from textral import Client, BulkOrchestrateFile, bulk_ingest_orchestrate

with Client(profile="hosted-prod") as client:
    result = bulk_ingest_orchestrate(
        client,
        namespace="my-docs",
        config={
            "embedding": {"provider": "openai", "model": "text-embedding-3-large", "dimensions": 1536, "provider_key_ref": "default"},
            "chunking":  {"profile": "generic"},
            "mode": "full",
        },
        files=[
            BulkOrchestrateFile(
                filename=name,
                bytes_=Path(name).read_bytes(),
                size_bytes=Path(name).stat().st_size,
                content_type="text/markdown",
            )
            for name in ("a.md", "b.md")
        ],
        on_existing="skip_if_unchanged",
        auto_finalize=True,
        concurrency=4,
        on_progress=lambda snap: print(snap.get("state"), f"{snap.get('progress_pct', 0)}%"),
    )

print(result.bulk_job_id, result.final_status["state"])`,
    },
  ],
};

