interface SpecLikeForSamples {
  paths?: Record<string, Record<string, { 'x-codeSamples'?: CodeSample[] } & Record<string, unknown>>>;
}

/** Walks the OpenAPI spec and attaches `x-codeSamples` to every flagship
 *  operation. Streaming samples are appended onto the sync query
 *  operation since both share `(POST, /v1/query)`. */
export function applyCodeSamples(spec: SpecLikeForSamples): void {
  if (!spec.paths) return;
  for (const entry of ALL_SAMPLES) {
    const ops = spec.paths[entry.key.path];
    if (!ops) continue;
    const op = ops[entry.key.method];
    if (!op) continue;
    op['x-codeSamples'] = entry.samples;
  }
  // Streaming samples + cookbook patterns augment the sync /v1/query operation.
  const queryOp = spec.paths['/v1/query']?.post;
  if (queryOp && Array.isArray(queryOp['x-codeSamples'])) {
    queryOp['x-codeSamples'] = [
      ...(queryOp['x-codeSamples'] as CodeSample[]),
      ...STREAMING_QUERY_SAMPLE,
      ...COOKBOOK_STRUCTURED_SIMPLE,
      ...COOKBOOK_STRUCTURED_NESTED,
      ...COOKBOOK_DOC_SUBSET,
      ...COOKBOOK_CUSTOM_PROMPT,
      ...COOKBOOK_FAILURE_RECOVERY,
      ...COOKBOOK_TOKEN_BUDGET,
    ];
  }
  // Named examples on the POST /v1/query request body — Scalar
  // surfaces these as a dropdown above the request body editor in
  // the Try-It panel.
  applyQueryRequestExamples(spec);
}

interface OperationWithBodyExamples {
  requestBody?: {
    content?: {
      'application/json'?: {
        examples?: Record<string, { summary: string; value: unknown }>;
      };
    };
  };
}

function applyQueryRequestExamples(spec: SpecLikeForSamples): void {
  if (!spec.paths) return;
  const op = spec.paths['/v1/query']?.post as OperationWithBodyExamples | undefined;
  if (!op?.requestBody?.content?.['application/json']) return;
  const baseEmbedding = {
    provider: 'openai',
    model: 'text-embedding-3-large',
    dimensions: 1536,
    provider_key_ref: 'default',
  };
  const baseInference = {
    provider: 'openai',
    model: 'gpt-4o-mini',
    provider_key_ref: 'default',
  };
  const baseChunking = { profile: 'generic' };
  const baseRetrieval = { strategy: 'hybrid_rrf', top_k_dense: 5, top_k_sparse: 5 };

  op.requestBody.content['application/json'].examples = {
    minimal: {
      summary: '1. Minimal RAG',
      value: {
        namespace: 'my-docs',
        query: 'What does the doc say about X?',
        embedding: baseEmbedding,
        inference: baseInference,
        chunking: baseChunking,
        retrieval: baseRetrieval,
      },
    },
    structured_simple: {
      summary: '2. Structured (simple)',
      value: {
        namespace: 'my-docs',
        query: 'Name two scholars connected to Alexandria.',
        embedding: baseEmbedding,
        inference: baseInference,
        chunking: baseChunking,
        retrieval: baseRetrieval,
        output: {
          mode: 'structured',
          schema: {
            type: 'object',
            properties: { scholars: { type: 'array', items: { type: 'string' } } },
            required: ['scholars'],
            additionalProperties: false,
          },
        },
      },
    },
    structured_nested: {
      summary: '3. Structured (nested + citations)',
      value: {
        namespace: 'my-docs',
        query: 'List the scholars mentioned and what each is known for.',
        embedding: baseEmbedding,
        inference: baseInference,
        chunking: baseChunking,
        retrieval: baseRetrieval,
        output: {
          mode: 'structured',
          schema: {
            type: 'object',
            properties: {
              scholars: {
                type: 'array',
                items: {
                  type: 'object',
                  properties: { name: { type: 'string' }, known_for: { type: 'string' } },
                  required: ['name', 'known_for'],
                  additionalProperties: false,
                },
              },
              citations: {
                type: 'array',
                items: {
                  type: 'object',
                  properties: { chunk_id: { type: 'string' }, quote: { type: 'string' } },
                  required: ['chunk_id', 'quote'],
                  additionalProperties: false,
                },
              },
            },
            required: ['scholars', 'citations'],
            additionalProperties: false,
          },
        },
      },
    },
    document_subset: {
      summary: '5. Document subset',
      value: {
        namespace: 'my-docs',
        document_ids: ['doc_01HABC...', 'doc_01HDEF...'],
        query: 'What does this contract say about termination?',
        embedding: baseEmbedding,
        inference: baseInference,
        chunking: baseChunking,
        retrieval: { ...baseRetrieval, top_k_dense: 10, top_k_sparse: 10 },
      },
    },
    custom_prompt: {
      summary: '6. Custom system prompt',
      value: {
        namespace: 'my-docs',
        query: 'Who was Eratosthenes?',
        embedding: baseEmbedding,
        inference: baseInference,
        chunking: baseChunking,
        retrieval: baseRetrieval,
        prompt: {
          system: 'You are a careful research assistant. Reply in two sentences max.',
        },
      },
    },
    token_budget: {
      summary: '8. Token-budget tweak',
      value: {
        namespace: 'my-docs',
        query: 'Summarise the corpus in two sentences.',
        embedding: baseEmbedding,
        inference: baseInference,
        chunking: baseChunking,
        retrieval: baseRetrieval,
        context: { max_context_tokens: 1500 },
      },
    },
  };
}

/** Exported so the regression test can pin the keys. */
export const FLAGSHIP_OPERATION_KEYS: SampleKey[] = ALL_SAMPLES.map((e) => e.key);
